sys_script_include.script:
var IllumioSyncFilterUtils = Class.create();

/**
 * Sync Filter evaluation: turning a filter into the workload sys_ids it matches, and rendering
 * those workloads as CSV.
 *
 * The fourth file of the split, and the one that was missing. IllumioSyncUtils is pure helpers
 * (no database, no `gs`, so the condition parser is testable in a plain Node harness),
 * IllumioSyncRepoUtils is data access, and IllumioUtils is coordination -- but IllumioUtils had
 * become coordination *of everything*: PCE configuration, label groups, job records, discovery,
 * deletion and, sitting in the middle of it, the Sync Filter evaluator. At 2,800 lines the
 * evaluator was hard to find and harder to reason about as a unit, and it has exactly one
 * subject.
 *
 * Nothing here belongs in the other two. Every method touches the database or calls `gs`, so
 * IllumioSyncUtils is out by its own rule; none of them is a single query, so
 * IllumioSyncRepoUtils is out too. They are coordination, which is what this file is for --
 * coordination of one thing rather than of everything.
 *
 * ONE SUBJECT: given a Sync Filter (or every Sync Filter on a PCE Configuration), which workloads
 * does it match, and what do those workloads look like as a file. Sync, deletion and every
 * preview enter here and nowhere else, which is what keeps a preview a preview -- it resolves
 * workloads by the same code the sync it is previewing will use.
 *
 * @see IllumioSyncUtils     pure helpers
 * @see IllumioSyncRepoUtils data access
 * @see JIRA/sync-optimization/sync-callchain.MD  phase 1 of the sync chain is this file
 */
IllumioSyncFilterUtils.prototype = {

    /**
     * @param {Object} [syncUtils] IllumioSyncUtils instance, constructed when omitted
     * @param {Object} [repo] IllumioSyncRepoUtils instance, constructed when omitted
     */
    initialize: function(syncUtils, repo) {
        this.logger = new IllumioLogger(null, 'IllumioSyncFilterUtils');
        this.syncUtils = syncUtils || new IllumioSyncUtils();
        this.repo = repo || new IllumioSyncRepoUtils(this.syncUtils);
    },

    /**
     * Point this evaluator's syslog lines at a job. Chainable onto the constructor.
     *
     * WHY THIS EXISTS, and it is the reason phase 1 looked silent. The constructor builds its
     * logger as `new IllumioLogger(null, ...)`, so every line _trace writes carries the `[-]`
     * prefix IllumioLogger uses for "no job". The correlated trail for a run is pulled back with
     *
     *     message STARTSWITH "[<job sys_id>]"
     *
     * -- the filter IllumioUtils.jobTraceLogger documents and the only practical way to read one
     * run's lines out of syslog_app_scope. `[-]` does not match it. So every per-term line, every
     * drain heartbeat and every filter total this class writes WAS being written, and none of it
     * could be retrieved with the run it belonged to. Phase 1 was the one stretch whose
     * commentary fell outside the trail, which reads exactly like a phase that logs nothing.
     *
     * The _progress lines were unaffected, which is what made this hard to see: they reach the
     * job record through the caller's own job-scoped sink, so the two lines bracketing the
     * silence showed up while everything between them did not.
     *
     * The repo's logger is set here too. This class constructs it, so there is nowhere else that
     * can, and its queries are inside the same stretch.
     *
     * Nil is allowed and is not a mistake: GetLabelGroupsAjax and the save-time filter check run
     * with no job at all, and their lines correctly stay under `[-]`.
     *
     * @param {String} jobSysId sys_id of the scheduled job this evaluation belongs to
     * @returns {Object} this
     */
    setJobContext: function(jobSysId) {
        this.logger.setContext(jobSysId);

        if (this.repo && this.repo.logger) {
            this.repo.logger.setContext(jobSysId);
        }

        return this;
    },

    // Workloads per query when reading rows back out for the CSV. Same value as everywhere else
    // that builds an IN clause; see IllumioSyncUtils.CI_CHUNK_SIZE.
    CSV_BATCH_SIZE: 500,

    CSV_HEADERS: ['sys_id', 'hostname', 'source_table', 'known_to_pce', 'conflicts',
        'pce_workload_href', 'servicenow_cmdb_identifier', 'labels'],

    // Wall-clock gap after which a drain loop says it is still alive. Short enough that nobody
    // watching concludes the job is wedged, long enough that a drain finishing inside it stays
    // silent and adds nothing to syslog.
    HEARTBEAT_INTERVAL_MS: 15000,

    /**
     * Report progress to whoever is watching, if anyone is.
     *
     * Phase 1 is set-based and fast per query, but a single GlideAggregate over a large label
     * table is tens of seconds on its own, and a CMDB drain is longer. It used to write nothing
     * at all until it finished -- 26 seconds of silence on an 83k run, minutes on a bigger one --
     * which is indistinguishable from a job that is wedged. The caller decides where the line
     * goes, because this evaluator is also called from UI Actions that have no job record.
     *
     * syslog gets the line either way, so behaviour is unchanged for callers that pass nothing.
     *
     * @param {Function} onProgress Optional - called with the message
     * @param {String} message Human-readable, addressed to whoever clicked the button
     */
    _progress: function(onProgress, message) {
        this.logger.info('[IllumioSyncFilterUtils] ' + message);

        if (typeof onProgress === 'function') {
            try {
                onProgress(message);
            } catch (ex) {
                // A progress sink that throws must never take the evaluation down with it. The
                // work is the point; the commentary is not.
                this.logger.warn('[IllumioSyncFilterUtils] Progress callback threw: ' + ex);
            }
        }
    },

    /**
     * Syslog only. For lines that exist to diagnose a hang rather than to tell the operator what
     * the run decided.
     *
     * The per-term and per-drain lines were on the job record and are the reason a run with a
     * handful of filters produced dozens of near-identical lines naming the same filter. They are
     * still worth having: one GlideAggregate over a large label table is the single
     * longest-running query in phase 1, and without a line per term that whole stretch looks like
     * one hang. Keeping them in syslog means "which term is it stuck on" is still answerable from
     * the application logs without the job record carrying it.
     *
     * @param {String} message
     */
    _trace: function(message) {
        this.logger.info('[IllumioSyncFilterUtils] ' + message);
    },

    /**
     * A throttled "still running" line for a drain loop. Syslog only.
     *
     * WHY WALL-CLOCK AND NOT A BATCH COUNTER. _matchCmdbCondition already had a heartbeat --
     * one line every 20 batches -- and a real deletion preview still ran 193 seconds with
     * nothing on it. The assumption behind a batch counter is that batches are cheap and cost
     * about the same, so N of them is a predictable interval. They are not: each batch is a
     * query whose cost depends on the table, its indexes and how far the extent narrows it, and
     * at ~5s a batch "every 20" is one line every 100 seconds. Worse, it fails in the wrong
     * direction -- the slower the batches, the longer the silence, when slow is exactly when
     * somebody is watching. Wall-clock inverts that: the interval is the interval whatever a
     * batch costs.
     *
     * The other two drains (shape B's extent scan and shape C's label resolve) had no heartbeat
     * of any kind and were silent for their whole duration however long that was.
     *
     * Nothing here reaches the job record. These lines answer "is it alive, and which batch is
     * it on", which is diagnostic and per-batch -- the caller already puts one line carrying the
     * same totals on the record when the drain ends.
     *
     * @param {String} label Filter label, so the line names what is running
     * @param {String} noun What `processed` counts -- 'CI(s)', 'workload(s)', 'label match(es)'
     * @returns {Function} tick(processed, added), called once per batch
     */
    _makeHeartbeat: function(label, noun) {
        var self = this;
        var startedAt = new Date().getTime();
        var lastAt = startedAt;

        return function(processed, added) {
            var now = new Date().getTime();

            // Returns before building any string, so a drain that never trips the interval pays
            // one subtraction per batch and concatenates nothing.
            if (now - lastAt < self.HEARTBEAT_INTERVAL_MS) {
                return;
            }
            lastAt = now;

            self._trace(label + ': still running -- ' + processed + ' ' + noun +
                ' processed, ' + added + ' workload(s) matched so far' +
                self.syncUtils.since(startedAt));
        };
    },

    /**
     * Eligible workload sys_ids for a PCE Configuration, across all its Sync Filters of one type.
     *
     * Multiple active filters are OR'd and globally deduplicated: a workload matched by two of
     * them must still reach the payload once.
     *
     * @param {String} configSysId sys_id of the PCE Configuration
     * @param {String} type 'inclusion' or 'deletion'
     * @param {Function} [onProgress] Called with each progress line
     * @returns {Object} { hasFilter: Boolean, sysIds: Array or null }
     *   - No active Sync Filter of this type: { hasFilter: false, sysIds: null }. The two callers
     *     read that opposite ways on purpose -- sync falls back to every candidate workload,
     *     deletion refuses. See sync-callchain.MD.
     */
    getEligibleWorkloadSysIdsByConfig: function(configSysId, type, onProgress) {
        var result = {
            hasFilter: false,
            sysIds: null
        };

        // Read as plain objects in one query rather than evaluated straight off a live cursor.
        // Evaluating a filter opens further queries, and this one would otherwise have to stay
        // open across all of them.
        var filters = this.repo.getActiveSyncFilters(configSysId, type);

        if (filters.length === 0) {
            // No claim about what happens next. The two callers read this outcome opposite ways
            // -- sync falls back to every candidate workload, deletion refuses -- and this line
            // used to assert the sync reading on both, so a deletion that stopped here said "all
            // workloads are eligible for sync" immediately before deleting nothing.
            this._progress(onProgress, 'Found active ' + type + ' Sync Filters: 0');
            return result;
        }

        result.hasFilter = true;

        // JOB RECORD LINE 1 OF 2. R35 fixed the job record's phase 1 output at exactly two lines:
        // this one and the summary evaluateFilters closes with. Everything else phase 1 emits is
        // syslog. Both are flat in filter count and in workload count.
        //
        // The type is named here and not in evaluateFilters, which is deliberately scope-blind --
        // it is handed a list and does not know or care whether it came from a configuration, a
        // type, or a single record. Someone reading a deletion job's log needs to see the word
        // "deletion" before the work starts.
        this._progress(onProgress, 'Found active ' + type + ' Sync Filters: ' + filters.length);

        result.sysIds = this.evaluateFilters(filters, configSysId, onProgress).sysIds;

        return result;
    },

    /**
     * Evaluate a list of Sync Filters into one deduplicated set of workload sys_ids.
     *
     * THE one phase 1. Sync, deletion, the PCE-Configuration exports and the single-filter
     * preview all arrive here; a PCE Configuration passes every eligible filter, a Sync Filter
     * preview passes a list of one. There is no fast path for the list of one -- it builds the
     * same set and calls the same setToArray as a list of twenty. A preview that took a different
     * route through phase 1 would be previewing something other than the run it claims to
     * predict, and the saving it bought was one pass over a list the caller is about to render to
     * CSV anyway.
     *
     * OR across filters, deduplicated globally: a workload matched by two of them must still
     * reach the payload once -- syncing it twice would mean a wasted bulk_update, or a duplicate
     * bulk_create for an unknown workload.
     *
     * Filters write their matches DIRECTLY into the run's set. Each one used to return its own
     * array, which the caller then unioned in, so at the peak of filter N the run held that
     * filter's array, its label set, and the accumulated set all at once.
     *
     * SATURATION. Once the set holds every workload the configuration has, no later filter can
     * add anything -- they are ORed, and every filter shape ends in a query carrying
     * `duplicate=false` on this configuration, which is exactly what the ceiling counts. The loop
     * stops there. It can only ever truncate the loop and never adds a sys_id, so the result is
     * always a subset of what the full loop would produce; the failure mode of a wrong ceiling is
     * "too few", never "too many". Equality is pigeonhole, not a heuristic.
     *
     * @param {Array} filters Filter objects from IllumioSyncRepoUtils
     * @param {String} configSysId sys_id of the PCE Configuration they all belong to
     * @param {Function} [onProgress] Called with each progress line
     * @returns {Object} { sysIds: Array, skipped: Array of { name, errors } }
     */
    evaluateFilters: function(filters, configSysId, onProgress) {
        var outcome = {
            sysIds: [],
            skipped: []
        };

        var allSysIds = {};
        var distinct = 0;

        // The saturation ceiling, taken once and only where it can change the outcome: a run with
        // a single filter ends after that filter whatever the count says, so taking it there is a
        // COUNT aggregate over the whole workload table done purely to be ignored. -1 means "not
        // taken yet"; 0 is a real answer (a configuration with no eligible workloads).
        //
        // The line reporting it is emitted where it is computed rather than up front, for the
        // same reason: it is the saturation check's denominator, so runs that never test
        // saturation neither pay for it nor mention it.
        var population = -1;

        var considered = 0;
        var phaseStartedAt = new Date().getTime();

        for (var index = 0; index < filters.length; index++) {
            considered++;

            var evaluated = this.evaluateSyncFilter(
                filters[index], allSysIds, onProgress,
                (index + 1) + '/' + filters.length);

            // A filter that cannot be evaluated contributes nothing rather than everything, and
            // the run CONTINUES to the next filter. Failing open here would sync workloads nobody
            // asked for; aborting the run would let one half-authored filter stop a sync that the
            // other filters could complete. Skipping is the only option that is both safe and
            // survivable.
            //
            // R35: `_trace`, not `_progress` -- syslog only, deliberately off the scheduled job
            // record. The reason a filter was skipped is diagnostic detail about one record, not
            // a statement of what the run decided, and it is addressed to whoever fixes the
            // filter rather than to whoever is watching the job.
            //
            // This does NOT hide it from the author: `outcome.skipped` carries the name and the
            // errors, and getWorkloadsBySyncFilter turns them into the message the single-filter
            // preview displays. That path was always the return value, never this log line.
            if (evaluated.errors.length > 0) {
                this._trace('Skipping Sync Filter "' + filters[index].name +
                    '": ' + evaluated.errors.join(' '));
                outcome.skipped.push({
                    name: filters[index].name,
                    errors: evaluated.errors
                });
                continue;
            }

            distinct += evaluated.added;

            // Nothing left to skip, so there is nothing to decide and no reason to count.
            if (index >= filters.length - 1) {
                continue;
            }

            if (population === -1) {
                var countStartedAt = new Date().getTime();
                population = this.repo.countEligibleWorkloads(configSysId);
                this._trace('Total Candidate Workloads - ' + population +
                    this.syncUtils.since(countStartedAt));
            }

            // Counted, never measured. setToArray(allSysIds).length here would build a full array
            // of every matched sys_id once per filter and throw each one away -- a second
            // full-size allocation per iteration, for a comparison two integers answer.
            if (population > 0 && distinct >= population) {
                this._trace('Saturated: all ' + population +
                    ' candidate workload(s) are matched. Skipping the remaining ' +
                    (filters.length - index - 1) + ' Sync Filter(s) -- they are ORed with what ' +
                    'is already matched and cannot add anything.');
                break;
            }
        }

        outcome.sysIds = this.syncUtils.setToArray(allSysIds);

        // `considered`, not filters.length: a saturated run stops short, and a count that claimed
        // to have evaluated filters it skipped would contradict the line above it. Only said when
        // the two differ -- on the ordinary run where every filter ran it is noise.
        if (considered < filters.length) {
            this._trace(considered + ' of ' + filters.length + ' filter(s) evaluated.');
        }

        this._trace('Eligible Workloads: ' + outcome.sysIds.length +
            this.syncUtils.since(phaseStartedAt));

        // JOB RECORD LINE 2 OF 2. The whole of phase 1 in one line, and the only one this method
        // puts on the record.
        //
        // "Eligible" is filters that evaluated and contributed; "Skipped" is filters refused by
        // the shape rules. On a saturated run the two do not sum to the filter count -- the
        // remainder was never evaluated because it could not have added anything, and the syslog
        // line above says so. Not restated here: this line exists to be the same length whatever
        // the run did.
        //
        // The match count is free. outcome.sysIds was already materialised on the line above it
        // for the return value, so this reads a length rather than doing any counting of its own.
        this._progress(onProgress, 'Evaluated Sync Filters: ' +
            (considered - outcome.skipped.length) + ' Eligible. ' +
            outcome.skipped.length + ' Skipped. ' +
            outcome.sysIds.length + ' matches' +
            this.syncUtils.since(phaseStartedAt));

        return outcome;
    },

    /**
     * Workloads matching one Sync Filter.
     *
     * A filter is two encoded queries authored in condition builders -- one over the label table,
     * one over the CMDB source table -- ANDed together. Sync Filter Groups and filter items are
     * gone; see JIRA/sync-optimization/points.MD R6-R8 for why.
     *
     * @param {String} syncFilterSysId sys_id of the Sync Filter record
     * @param {Boolean} [skipActiveCheck] Skip the active check (a preview is most useful on a
     *   filter that is not switched on yet)
     * @param {Boolean} [sysIdsOnly] Return sysIds rather than full workload objects
     * @param {Function} [onProgress] Called with each progress line
     * @returns {Object} { success, workloads, message }, or { success, sysIds, message }
     */
    getWorkloadsBySyncFilter: function(syncFilterSysId, skipActiveCheck, sysIdsOnly, onProgress) {
        var result = {
            success: false,
            workloads: [],
            message: ''
        };

        try {
            var filter = this.repo.getSyncFilter(syncFilterSysId);
            if (!filter) {
                result.message = 'Sync Filter not found';
                return result;
            }

            if (!skipActiveCheck && !filter.active) {
                result.message = 'Sync Filter is not active';
                return result;
            }

            if (gs.nil(filter.pce_configuration)) {
                result.message = 'No PCE Configuration associated with Sync Filter';
                return result;
            }

            // A list of one, through the same loop every other caller uses. Not a shortcut past
            // it: the saturation ceiling, the deduplication and the final setToArray all run
            // exactly as they would for a configuration with twenty filters, so what a preview
            // shows is what the sync would do.
            var evaluated = this.evaluateFilters(
                [filter], filter.pce_configuration, onProgress);

            // Reported rather than swallowed: this is the path the preview UI actions use, and
            // the author needs to see the same message the save-time rule would have shown.
            if (evaluated.skipped.length > 0) {
                result.message = evaluated.skipped[0].errors.join(' ');
                return result;
            }

            var finalSysIds = evaluated.sysIds;

            if (sysIdsOnly) {
                result.sysIds = finalSysIds;
                result.success = true;
                result.message = 'Found ' + finalSysIds.length + ' matching workloads';
            } else {
                if (finalSysIds.length > 0) {
                    result.workloads = this._fetchWorkloadRecords(finalSysIds);
                }
                result.success = true;
                result.message = 'Found ' + result.workloads.length + ' matching workloads';
            }

        } catch (ex) {
            this.logger.error('[IllumioSyncFilterUtils.getWorkloadsBySyncFilter] Exception: ' + ex);
            result.message = 'Exception occurred: ' + ex;
        }

        return result;
    },

    /**
     * Evaluate one Sync Filter, adding the workloads it matches to the run's set.
     *
     * The two conditions are independent and ANDed. Which side is materialised is not a
     * decision: the label side resolves to workload sys_ids and so is bounded by the workload
     * count, while the CMDB side is bounded only by the size of a CMDB table. The CMDB side is
     * therefore always the streamed one, and the label side is the guard it is filtered against.
     *
     * The extent is a third predicate, ANDed with whatever the conditions matched. It is no
     * longer a separate pass: every shape below ends in a workload query, and the extent rides on
     * that query beside `duplicate=false` rather than being applied to its output afterwards.
     * A filter carrying only an extent is a valid filter, not an empty one.
     *
     * FOUR SHAPES, and each one ends by writing into allSysIds rather than returning an array:
     *
     *   A  nothing set          SKIP
     *   B  extent only          one streamed workload query
     *   C  label (no cmdb)      label aggregates, then the label set windowed back through the
     *                           workload table for `duplicate` and the extent
     *   D  cmdb (± label)       CI drain, each batch resolved to workloads with `duplicate` and
     *                           the extent already in the query, guarded by the label set
     *
     * @param {Object} filter Filter object from IllumioSyncRepoUtils
     * @param {Object} allSysIds The run's result set. GROWN IN PLACE, and read as the negative
     *   guard: whatever an earlier filter already matched is skipped rather than re-resolved.
     * @param {Function} [onProgress] Called with each progress line
     * @param {String} [position] "2/3", for the progress lines when evaluating several
     * @returns {Object} { added: Number, errors: Array } - errors non-empty means matched nothing
     */
    evaluateSyncFilter: function(filter, allSysIds, onProgress, position) {
        var self = this;
        var evaluated = {
            added: 0,
            errors: []
        };

        var label = 'Sync Filter "' + filter.name + '"' + (position ? ' (' + position + ')' : '');

        // The count the most recent condition line put on the job record. The closing "Matched:"
        // line is emitted ONLY when the filter's contribution differs from it -- on the ordinary
        // shapes the last condition line already carries the total and a second line saying the
        // same number is the redundancy this restructure exists to remove.
        var lastReported = null;

        this._trace('Evaluating Sync Filter ' + (position || '1/1') + ' - ' +
            filter.name);

        var hasLabelCondition = !this.syncUtils.isConditionEmpty(filter.label_condition);
        var hasCmdbCondition = !this.syncUtils.isConditionEmpty(filter.cmdb_condition);

        // Split once here and passed down. Every shape needs it, and shape D's query runs once
        // per 500 CIs -- splitting inside that callback would be thousands of identical parses.
        var extentList = this.syncUtils.splitExtent(filter.extent);
        var hasExtent = extentList.length > 0;

        // Run-time enforcement of the rules that until now lived ONLY in the
        // `Validate Sync Filter Extent` / `Validate Sync Filter Conditions` business rules. Those
        // fire on save, so a filter arriving by update set, import or setWorkflow(false) never
        // meets them -- and an import is exactly how a filter reaches a production instance.
        //
        // What the gap costs: shapes C and D apply the extent by ORing conditions onto a query
        // (IllumioSyncRepoUtils._addExtentConditions), so an empty extentList adds NO conditions
        // at all and the filter silently widens to every non-duplicate workload its conditions
        // matched -- `unknown` ones included. On a deletion run that is workloads nobody selected.
        //
        // Errors rather than a throw, unlike the threshold limits. An unresolvable limit cancels
        // the job because it is a property of the whole run; a misconfigured filter is a property
        // of ONE filter, and this method already skips a filter it cannot parse (the CMDB
        // condition with no table, below). Skipping contributes nothing, which is the fail-closed
        // direction, and evaluateFilters reports it by name.
        //
        // R35: this block moved ABOVE the shape A check, which it used to sit below. The old order
        // meant an all-empty DELETION filter was caught by shape A and passed over quietly, when
        // the deletion message below says exactly what is wrong with it. Checking type first gives
        // each type its own message and leaves shape A as purely the inclusion case.
        if (filter.type === 'deletion') {
            if (!hasExtent) {
                evaluated.errors.push('Deletion Sync Filters must have at least one Extent value ' +
                    'selected. This one has none, so it would target every workload its ' +
                    'conditions match, including workloads that are not on the PCE. Set the ' +
                    'Extent to "Managed" and/or "Unmanaged".');
                return evaluated;
            }

            for (var extentIndex = 0; extentIndex < extentList.length; extentIndex++) {
                // Exact compare, not split("-")[0]. `unknown` means the workload is not on the
                // PCE yet, so there is no enforcement mode that could qualify it and the choice
                // list offers no `unknown-*` value. Settled 2026-09-29 -- and this deliberately
                // mirrors the business rule character for character, because two checks of the
                // same rule that disagree are worse than one.
                if (extentList[extentIndex] === 'unknown') {
                    evaluated.errors.push('Deletion Sync Filters cannot include "Unknown" in the ' +
                        'Extent. Only Managed and Unmanaged workloads exist on the PCE to be ' +
                        'deleted.');
                    return evaluated;
                }
            }
        }

        // SHAPE A. Empty means all three empty, not just the two conditions. The extent is a
        // predicate over the workload like any other -- "every unmanaged workload in this
        // configuration" is a complete, deliberate filter.
        //
        // It still contributes NOTHING, exactly as before: a filter with nothing set at all is far
        // more likely to be half-finished than a deliberate "sync every workload", and matching
        // everything is the direction that cannot be undone.
        //
        // R35: what changed is that it is now REPORTED instead of passed over in a progress line.
        // This was the one invalid shape that failed quietly, which made "Eligible Workloads: 0"
        // indistinguishable from a filter nobody finished authoring. evaluateFilters names it in
        // `skipped`; getWorkloadsBySyncFilter surfaces the message, so the preview an author runs
        // now says why it matched nothing rather than reporting a confident zero.
        //
        // Deletion filters cannot reach here -- the block above returns on !hasExtent -- so this
        // is the inclusion rule: at least one of Extent, CMDB Condition or Label Condition.
        if (!hasLabelCondition && !hasCmdbCondition && !hasExtent) {
            evaluated.errors.push('Inclusion Sync Filters must have at least one of Extent, ' +
                'CMDB Condition or Label Condition set. This one has none of the three, so there ' +
                'is nothing to match on. Set a condition, or set the Extent to select every ' +
                'workload in a given state.');
            return evaluated;
        }

        // Syslog only now. The job record gets the three condition lines below, which say the
        // same thing with counts attached; this one said it before the work so that a job sitting
        // at "Evaluating filter" showed what it was sitting on, and syslog still serves that.
        this._trace(label + ': evaluating ' +
            this._describeSides(hasLabelCondition, hasCmdbCondition, hasExtent) + '.');

        // SHAPE B, extent only. There is no matched set to narrow, so the extent runs as the
        // query itself instead of as a predicate over one -- streamed, because the result of an
        // extent-only filter is bounded by the workload count and returning it whole would put a
        // full-size array beside the set it is about to be merged into.
        if (!hasLabelCondition && !hasCmdbCondition) {
            var extentStartedAt = new Date().getTime();

            // This drain used to emit nothing at all between the "evaluating" line above and the
            // "Extent: Found" line below. An extent-only DELETION filter is the shape most likely
            // to sit here -- the extent is mandatory on deletion filters, so a filter with no
            // conditions lands in shape B by construction -- and that is the preview that ran 193
            // seconds in silence.
            var extentBeat = this._makeHeartbeat(label, 'workload(s)');
            var extentWalked = 0;

            var scanned = this.repo.eachWorkloadSysIdInExtent(
                filter.pce_configuration, extentList, filter.source_table,
                this.syncUtils.WORKLOAD_CHUNK_SIZE,
                function(batch) {
                    evaluated.added += self.syncUtils.unionInto(allSysIds, batch);

                    // Counted here rather than read back from `scanned`, which is not assigned
                    // until the drain returns.
                    extentWalked += batch.length;
                    extentBeat(extentWalked, evaluated.added);
                });

            this._trace('Label Condition: Not set');
            this._trace('CMDB Condition: Not set');
            this._trace('Extent: Found (Matched ' + evaluated.added +
                ' workload(s)' + this._newOf(scanned, evaluated.added) + ')' +
                this.syncUtils.since(extentStartedAt));

            return evaluated;
        }

        if (hasCmdbCondition && gs.nil(filter.source_table)) {
            evaluated.errors.push('The CMDB Condition has no table to run against. ' +
                'Set a Class Mapping on the Sync Filter.');
            return evaluated;
        }

        var labelStartedAt = new Date().getTime();

        // SHAPES C AND D-with-label, as ONE streaming pass. R50.
        //
        // The label side now drives and the CMDB condition rides on the per-window query, which is
        // the reverse of what this function used to do. Both shapes end here; only the shape with
        // a CMDB condition and NO label condition falls through to the drain below.
        //
        // Three result-sized structures became one. The term array and the label set are gone --
        // the walk streams into windows of WORKLOAD_CHUNK_SIZE and `allSysIds` is the only thing
        // that grows with the answer.
        if (hasLabelCondition) {
            var streamed = this._streamLabelCondition(
                filter, extentList, allSysIds, evaluated.errors, label);

            if (evaluated.errors.length > 0 || !streamed) {
                return evaluated;
            }

            evaluated.added = streamed.added;

            // The label condition's OWN result, before `duplicate`, the extent and the CMDB
            // condition narrow it and before the negative guard drops what the run already has.
            // Reporting the post-narrowing number here instead would hide the gap between "the
            // condition selected this many" and "this many survived".
            //
            // ACROSS TERMS THIS COUNTS EMISSIONS, NOT DISTINCT WORKLOADS. Terms are OR'd and the
            // walk no longer holds a set to deduplicate against, so a workload satisfying two
            // terms is counted twice here. It is still only resolved and added once -- the
            // negative guard sees it in `allSysIds` the second time. The term count is printed so
            // the number is readable rather than merely wrong-looking; with one term, which is
            // the common shape, it is exactly the old figure.
            lastReported = streamed.emitted;
            this._trace('Label Condition: Found (Matched ' + lastReported +
                ' workload(s)' + (streamed.terms > 1 ?
                    ' across ' + streamed.terms + ' term(s), emissions not distinct' : '') +
                ')' + this.syncUtils.since(labelStartedAt));

            this._trace(hasCmdbCondition ?
                'CMDB Condition: Applied within the label window query (included below)' :
                'CMDB Condition: Not set');

            // Same reasoning as the old shape D: there is no point in the run where the extent has
            // been applied and the rest has not, so it gets no separate count.
            this._trace(hasExtent ?
                'Extent: Applied within the label window query (included below)' :
                'Extent: Not set');

            this._trace(label + ': ' + streamed.added + ' workload(s) added (' +
                streamed.considered + ' of ' + streamed.emitted +
                ' reached a window query, the rest the run already had).');

            this._reportFilterTotal(evaluated.added, lastReported);
            return evaluated;
        }

        this._trace('Label Condition: Not set');

        // SHAPE D WITHOUT A LABEL CONDITION. Nothing to stream from, so the CI drain stays as it
        // was -- and it was always one result-sized structure, so nothing is lost by leaving it.
        if (hasCmdbCondition) {
            var cmdbStartedAt = new Date().getTime();

            // null guard, not a label set: this branch is only reached when there is NO label
            // condition, so there is nothing to guard against. _matchCmdbCondition already treats
            // a nil guardSet as "admit everything" -- see unionIntoGuarded.
            var drained = this._matchCmdbCondition(
                filter, extentList, null, allSysIds, label);

            evaluated.added = drained.added;

            this._trace('CMDB Condition: Found (Matched ' + drained.added +
                ' workload(s) from ' + drained.ciTotal + ' CI(s) in ' + filter.source_table +
                ')' + this.syncUtils.since(cmdbStartedAt));

            // NOT "skipped". The extent is applied -- it rides on the same workload query as
            // `duplicate=false`, inside the drain, so it has already narrowed the number on the
            // line above. What is unavailable is a SEPARATE count for it, because there is no
            // point in the shape where the extent has been applied and the CMDB condition has
            // not. Saying "skipping extent" here would describe a run that did not happen.
            this._trace(hasExtent ?
                'Extent: Applied within the CMDB query (included in the count above)' :
                'Extent: Not set');

            // No closing "Matched:" line. The CMDB line above already carries this filter's whole
            // contribution -- the drain adds to the run and nothing narrows it afterwards.
            return evaluated;
        }

        // UNREACHABLE. Every shape now returns above: B at the extent-only branch, C and
        // D-with-label through _streamLabelCondition, D-without-label through the drain. What is
        // left is !hasLabelCondition && !hasCmdbCondition, which the extent-only branch already
        // took -- and the all-three-empty case errors out before any of them.
        //
        // Kept as a guard rather than deleted: falling off the end of this function would return
        // `evaluated` with added = 0 and no error, which is the silent-zero shape this whole
        // decision record is about.
        this.logger.error('[IllumioSyncFilterUtils] ' + label + ': reached the end of ' +
            'evaluateSyncFilter without matching a shape. hasLabel=' + hasLabelCondition +
            ' hasCmdb=' + hasCmdbCondition + ' hasExtent=' + hasExtent +
            '. This is a routing defect, not a filter problem.');
        evaluated.errors.push('Internal: this Sync Filter matched no evaluation shape. ' +
            'See the syslog entry from IllumioSyncFilterUtils for its condition flags.');
        return evaluated;
    },

    // R13. SHAPE C's old tail, replaced by _streamLabelCondition. It ran AFTER the label set was
    // fully materialised, walking that set 500 at a time to apply `duplicate` and the extent --
    // which is the pass the streaming walk now does inline, without the set existing.
    //
    // this._trace('CMDB Condition: Not set');
    //
    // var resolveStartedAt = new Date().getTime();
    // var resolved = this._resolveLabelMatches(extentList, labelMatches, allSysIds, label);
    //
    // evaluated.added = resolved.added;
    //
    // if (hasExtent) {
    //     lastReported = resolved.added;
    //     this._trace('Extent: Found (Matched ' + resolved.added +
    //         ' workload(s) of ' + resolved.considered + ' checked)' +
    //         this.syncUtils.since(resolveStartedAt));
    // } else {
    //     this._trace('Extent: Not set' + this.syncUtils.since(resolveStartedAt));
    // }
    //
    // this._reportFilterTotal(evaluated.added, lastReported);
    // return evaluated;

    /**
     * Close a filter out with its contribution, but only when that number is not already the last
     * one emitted.
     *
     * R35: syslog, like every other per-filter line. The `onProgress` parameter went with the
     * move -- nothing in this function reaches the job record any more.
     *
     * Shapes B, C-with-extent and D all end on a condition line that carries the filter's total,
     * and repeating it is exactly the duplication this restructure removes. Shape C without an
     * extent does not: its last line is the label condition's own count, which is taken before
     * `duplicate` and the negative guard narrow it. There the closing line is the only place the
     * filter's real contribution appears.
     *
     * @param {Number} added The filter's contribution to the run
     * @param {Number|null} lastReported Count on the most recent condition line
     */
    _reportFilterTotal: function(added, lastReported) {
        if (lastReported === added) {
            return;
        }

        this._trace('Matched: ' + added + ' workload(s) added to this run');
    },

    /**
     * ", N already matched by an earlier filter" -- suppressed when every match was new, which is
     * the case on the first filter and on any run whose filters do not overlap.
     *
     * Only meaningful where the gap between the two numbers is the union and nothing else, which
     * is shape B: the extent query returns every workload it matched and unionInto reports how
     * many of those the run did not already have. Shapes C and D narrow on other predicates in
     * the same pass, so their gap is not this.
     *
     * @param {Number} scanned Workloads the query returned
     * @param {Number} added Workloads that were new to the run
     * @returns {String} Empty string, or a clause to append inside the count parenthesis
     */
    _newOf: function(scanned, added) {
        if (scanned === added) {
            return '';
        }

        return ', ' + (scanned - added) + ' already matched by an earlier filter';
    },

    /**
     * "a label condition, a CMDB condition and an extent" -- for the progress line.
     *
     * @returns {String} Human-readable list of the sides that are set
     */
    _describeSides: function(hasLabelCondition, hasCmdbCondition, hasExtent) {
        var sides = [];

        if (hasLabelCondition) {
            sides.push('a label condition');
        }
        if (hasCmdbCondition) {
            sides.push('a CMDB condition');
        }
        if (hasExtent) {
            sides.push('an extent');
        }

        if (sides.length === 1) {
            return sides[0];
        }

        return sides.slice(0, sides.length - 1).join(', ') + ' and ' + sides[sides.length - 1];
    },

    /**
     * Workloads matching a filter's label condition.
     *
     * Each ^NQ group of the condition is one DNF term, evaluated in a single GlideAggregate and
     * ORed with the rest. One query per group however many dimensions the group ANDs, so the
     * query count scales with how the filter was authored and not with how much data there is.
     *
     * @param {Object} filter Filter object from IllumioSyncRepoUtils
     * @param {Array} errors Collects parse errors, in place
     * @param {String} [label] Filter label for the trace lines
     * @returns {Object|null} { workloadSysIdsMatchingLabelConditions: Object, distinct: Number },
     *   null when the condition would not parse. The count travels with the set because the only
     *   other way to get it back is Object.keys, which at 2M members is a full-size array built
     *   to be measured and dropped.
     */
    /**
     * SHAPES C AND D-with-label, as one streaming pass. R50.
     *
     * Replaces _matchLabelCondition + _resolveLabelMatches, and replaces the label guard set that
     * _matchCmdbCondition used to hold for the length of the CMDB drain.
     *
     * THE INVERSION. The CMDB side used to drive and the label side was a materialised lookup;
     * now the label side drives -- streamed -- and the CMDB condition is a per-window query. That
     * is only possible because row iteration is uncapped where grouped iteration is not, which is
     * the same measurement that fixed the correctness defect.
     *
     * Workloads are buffered to WORKLOAD_CHUNK_SIZE and resolved a window at a time, so the only
     * structure that grows with the result is `allSysIds` -- R27's one sanctioned exception. The
     * old shape held three: the term's array, the label set, and `allSysIds`.
     *
     * THE NEGATIVE GUARD IS WHY TERMS DO NOT DUPLICATE WORK. Terms are OR'd, so a workload matched
     * by term 1 is already in `allSysIds` when term 2 reaches it and never costs a second window
     * query. It is also what keeps a workload an earlier FILTER matched out of this one's queries,
     * which is the behaviour eachSetWindow had.
     *
     * @param {Object} filter Sync Filter record fields
     * @param {Array} extentList Extent entries from IllumioSyncUtils.splitExtent
     * @param {Object} allSysIds The run's result set. Grown in place, and read as the guard.
     * @param {Array} errors Parse errors are pushed here; a non-empty array means fail closed
     * @param {String} label Filter label for the trace lines
     * @returns {Object} { emitted, added, considered, terms }
     */
    /**
     * Reject a label condition naming a Label Dimension this configuration cannot use.
     *
     * THE ONE IMPLEMENTATION, called from both the save-time rule and the evaluator. The
     * `Validate Sync Filter Conditions` business rule states the contract this upholds: the label
     * rules live in one place so that "what is rejected on save and what is refused at run time
     * cannot drift apart". This rule needs a query, and IllumioSyncUtils is deliberately the
     * gs-free, DB-free half, so it could not go in the parser itself -- this method is where the
     * pure half and the repository half are joined instead.
     *
     * WHY IT EXISTS AT ALL. The Label Condition is a condition builder over the workload field
     * value table, and a reference qualifier cannot filter a picker there: an advanced qualifier
     * needs `current`, and a condition builder has no record of the target table. So the Label
     * Dimension picker offers every dimension on the instance, from every PCE Configuration, and
     * nothing stops the author choosing one that cannot match. It is caught here instead.
     *
     * @param {String} pceConfigSysId The filter's PCE Configuration
     * @param {Object} parsed Result of parseLabelCondition -- pass the SAME parse, not a re-parse
     * @param {Array} errors Messages are appended here; a non-empty array means refuse
     * @returns {Number} how many unusable dimensions were found
     */
    validateLabelDimensions: function(pceConfigSysId, parsed, errors) {
        if (gs.nil(pceConfigSysId) || !parsed || !parsed.terms || parsed.terms.length === 0) {
            return 0;
        }

        var unusable = this.repo.findUnusableLabelDimensions(
            pceConfigSysId, this.syncUtils.labelDimensionSysIds(parsed));

        for (var index = 0; index < unusable.length; index++) {
            var entry = unusable[index];

            if (entry.reason === "missing") {
                errors.push("The Label Condition names a Label Dimension that no longer exists (" +
                    entry.sysId + "). It was probably deleted after this filter was written. " +
                    "Remove that condition or choose a current dimension.");
                continue;
            }

            errors.push("The Label Condition uses the Label Dimension '" + entry.name +
                "', which belongs to PCE Configuration '" + entry.configName +
                "' and not to this filter's. It can never match a workload, so the filter would " +
                "sync nothing. Choose a dimension from this filter's PCE Configuration.");
        }

        return unusable.length;
    },

    _streamLabelCondition: function(filter, extentList, allSysIds, errors, label) {
        var self = this;
        var parsed = this.syncUtils.parseLabelCondition(filter.label_condition);

        // Fail closed, exactly as before. A mis-parsed condition that silently syncs the wrong
        // workloads is worse than one that syncs none.
        if (parsed.errors.length > 0) {
            for (var e = 0; e < parsed.errors.length; e++) {
                errors.push(parsed.errors[e]);
            }
            return null;
        }

        // Run time as well as save time, for the same reason evaluateSyncFilter re-checks the
        // extent rules: a business rule fires on save, and a filter arriving by update set or
        // import never passes through one. Same parse object, so the two cannot disagree about
        // which dimensions the condition names.
        if (this.validateLabelDimensions(filter.pce_configuration, parsed, errors) > 0) {
            return null;
        }

        var hasCmdb = !this.syncUtils.isConditionEmpty(filter.cmdb_condition);
        var windowSize = this.syncUtils.WORKLOAD_CHUNK_SIZE;

        var emitted = 0;      // qualified by the label condition, before any narrowing
        var considered = 0;   // actually reached a window query, i.e. survived the negative guard
        var added = 0;        // joined the run because of this filter
        var buffer = [];

        var beat = this._makeHeartbeat(label, 'label match(es)');

        var resolveWindow = function() {
            if (buffer.length === 0) {
                return;
            }

            // Shape D applies the CMDB condition in the same pass; shape C has none to apply and
            // takes the query it has always taken. Both carry `duplicate` and the extent.
            var survivors = hasCmdb ?
                self.repo.findSurvivingWorkloadsMatchingCmdb(
                    buffer, extentList, filter.source_table, filter.cmdb_condition) :
                self.repo.findSurvivingWorkloads(buffer, extentList);

            added += self.syncUtils.unionInto(allSysIds, survivors);
            buffer = [];
            beat(considered, added);
        };

        for (var termIndex = 0; termIndex < parsed.terms.length; termIndex++) {
            var termStartedAt = new Date().getTime();

            var termEmitted = this.repo.eachLabelTermWorkload(
                filter.pce_configuration, filter.class_mapping, parsed.terms[termIndex],
                function(workloadSysId) {
                    emitted++;

                    // Already in the run -- from an earlier term or an earlier filter -- so the
                    // answer cannot change and the window query would only re-derive it.
                    if (allSysIds[workloadSysId]) {
                        return true;
                    }

                    considered++;
                    buffer.push(workloadSysId);

                    if (buffer.length >= windowSize) {
                        resolveWindow();
                    }
                    return true;
                });

            this._trace(label + ': label term ' + (termIndex + 1) + ' of ' +
                parsed.terms.length + ' qualified ' + termEmitted + ' workload(s)' +
                this.syncUtils.since(termStartedAt));
        }

        // The remainder, which is every run whose count is not an exact multiple of the window.
        resolveWindow();

        return {
            emitted: emitted,
            considered: considered,
            added: added,
            terms: parsed.terms.length
        };
    },

    // R13. _matchLabelCondition, replaced by _streamLabelCondition above. It built the whole label
    // set before anything else ran, which is what made the CMDB side the streamed one and forced
    // the set to stay alive as a guard for the length of that drain.
    // _matchLabelCondition: function(filter, errors, label) {
    // var parsed = this.syncUtils.parseLabelCondition(filter.label_condition);
    //
    // // Fail closed. A mis-parsed condition that silently syncs the wrong workloads is worse
    // // than one that syncs none, and the save-time business rule reports these same strings
    // // from this same call, so validation and evaluation cannot drift apart.
    // if (parsed.errors.length > 0) {
    // for (var errorIndex = 0; errorIndex < parsed.errors.length; errorIndex++) {
    // errors.push(parsed.errors[errorIndex]);
    // }
    // return null;
    // }
    //
    // var workloadSysIdsMatchingLabelConditions = {};
    //
    // // Counted as we go, from unionInto's return value. The progress line used to call
    // // setToArray(...).length on this, which builds a full array of every matched sys_id and
    // // throws it away one expression later -- a second full-size allocation for a log line.
    // var distinct = 0;
    //
    // for (var termIndex = 0; termIndex < parsed.terms.length; termIndex++) {
    // // Per term, because one GlideAggregate over a large label table is the single
