    // *   how many label matches reached a query at all. The caller needs both: `added` is the
    // *   filter's contribution and the gap between them is what the negative guard skipped.
    // */
    // _resolveLabelMatches: function(extentList, labelMatches, allSysIds, label) {
    // var self = this;
    // var added = 0;
    // var considered = 0;
    //
    // // Silent for its whole duration before this. One window is one workload query, and a
